import { render } from "./engine.ts";

function usage(): never {
  throw new Error("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
}

async function main(): Promise<void> {
  const args = Bun.argv.slice(2);
  if (args.length !== 2) usage();

  const [templatePath, dataPath] = args;
  const [template, json] = await Promise.all([
    Bun.file(templatePath).text(),
    Bun.file(dataPath).text(),
  ]);
  let data: unknown;
  try {
    data = JSON.parse(json);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid JSON in ${dataPath}: ${message}`);
  }
  process.stdout.write(render(template, data));
}

main().catch(error => {
  const message = error instanceof Error ? error.message : String(error);
  process.stderr.write(`mini-template: ${message}\n`);
  process.exitCode = 1;
});

import { describe, expect, test } from "bun:test";
import { render } from "../src/engine.ts";

describe("interpolation", () => {
  test("escapes HTML and supports raw values", () => {
    const value = `&<>"'`;
    expect(render("{{value}} | {{{value}}}", { value }))
      .toBe("&amp;&lt;&gt;&quot;&#39; | &<>\"'");
  });

  test("resolves nested and missing paths", () => {
    expect(render("{{user.name}}/{{user.missing}}", { user: { name: "Ada" } })).toBe("Ada/");
  });

  test("rejects non-scalar interpolation", () => {
    expect(() => render("x {{user}}", { user: { name: "Ada" } }))
      .toThrow("Value 'user' cannot be rendered as scalar text at line 1, column 3");
  });
});

describe("blocks", () => {
  test("uses the specified truthiness rules", () => {
    for (const value of ["", 0, 0n, false, null, undefined, []]) {
      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("no");
    }
    for (const value of ["0", 1, {}, [0]]) {
      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("yes");
    }
  });

  test("supports nested blocks", () => {
    const template = "{{#if ready}}{{#if ok}}A{{else}}B{{/if}}{{else}}C{{/if}}";
    expect(render(template, { ready: true, ok: false })).toBe("B");
  });

  test("iterates arrays with context and root fallback", () => {
    const template = "{{#each users}}[{{@index}}:{{this.name}}/{{title}}]{{else}}empty{{/each}}";
    expect(render(template, { title: "T", users: [{ name: "A" }, { name: "B" }] }))
      .toBe("[0:A/T][1:B/T]");
    expect(render(template, { title: "T", users: [] })).toBe("empty");
  });

  test("supports nested loops", () => {
    const template = "{{#each groups}}{{#each this}}({{@index}}={{this}}){{/each}}{{/each}}";
    expect(render(template, { groups: [["a", "b"], ["c"]] })).toBe("(0=a)(1=b)(0=c)");
  });
});

describe("syntax and preservation", () => {
  test("preserves whitespace and removes comments", () => {
    expect(render(" a\n {{! ignored }}\t b ", {})).toBe(" a\n \t b ");
  });

  test.each([
    ["{{#wat x}}{{/wat}}", "Unknown block", "line 1, column 1"],
    ["a\n{{else}}", "else outside a block", "line 2, column 1"],
    ["{{#if x}}{{else}}{{else}}{{/if}}", "Duplicate else", "line 1, column 18"],
    ["{{#if x}}{{/each}}", "Mismatched close", "line 1, column 10"],
    ["x {{#if x}}", "Unclosed if block", "line 1, column 3"],
    ["x {{name", "Unclosed tag", "line 1, column 3"],
  ])("reports structural error for %s", (template, message, location) => {
    expect(() => render(template, { x: true })).toThrow(message);
    expect(() => render(template, { x: true })).toThrow(location);
  });
});

type Location = { line: number; column: number };

type TextNode = { kind: "text"; value: string };
type ValueNode = { kind: "value"; path: string; escaped: boolean; location: Location };
type BlockNode = {
  kind: "if" | "each";
  path: string;
  body: Node[];
  alternate: Node[];
  location: Location;
};
type Node = TextNode | ValueNode | BlockNode;

type Frame = {
  block: BlockNode;
  parent: Node[];
  inElse: boolean;
};

type Context = { current: unknown; index: number | undefined };

function locationAt(source: string, offset: number): Location {
  let line = 1;
  let column = 1;
  for (let i = 0; i < offset; i++) {
    if (source.charCodeAt(i) === 10) {
      line++;
      column = 1;
    } else {
      column++;
    }
  }
  return { line, column };
}

function syntaxError(message: string, location: Location): Error {
  return new Error(`${message} at line ${location.line}, column ${location.column}`);
}

function requirePath(tag: string, prefix: string, location: Location): string {
  const path = tag.slice(prefix.length).trim();
  if (!path) throw syntaxError(`Missing path for ${prefix.trim()}`, location);
  return path;
}

function parse(template: string): Node[] {
  const root: Node[] = [];
  const stack: Frame[] = [];
  let output = root;
  let cursor = 0;

  while (cursor < template.length) {
    const start = template.indexOf("{{", cursor);
    if (start === -1) {
      output.push({ kind: "text", value: template.slice(cursor) });
      break;
    }
    if (start > cursor) output.push({ kind: "text", value: template.slice(cursor, start) });

    const triple = template.startsWith("{{{", start);
    const close = triple ? "}}}" : "}}";
    const contentStart = start + (triple ? 3 : 2);
    const end = template.indexOf(close, contentStart);
    const location = locationAt(template, start);
    if (end === -1) throw syntaxError("Unclosed tag", location);

    const tag = template.slice(contentStart, end).trim();
    cursor = end + close.length;
    if (!tag) throw syntaxError("Empty tag", location);

    if (triple) {
      output.push({ kind: "value", path: tag, escaped: false, location });
      continue;
    }
    if (tag.startsWith("!")) continue;

    if (tag.startsWith("#")) {
      let kind: "if" | "each";
      let path: string;
      if (tag === "#if" || tag.startsWith("#if ")) {
        kind = "if";
        path = requirePath(tag, "#if", location);
      } else if (tag === "#each" || tag.startsWith("#each ")) {
        kind = "each";
        path = requirePath(tag, "#each", location);
      } else {
        throw syntaxError(`Unknown block '${tag}'`, location);
      }
      const block: BlockNode = { kind, path, body: [], alternate: [], location };
      output.push(block);
      stack.push({ block, parent: output, inElse: false });
      output = block.body;
      continue;
    }

    if (tag === "else") {
      const frame = stack.at(-1);
      if (!frame) throw syntaxError("else outside a block", location);
      if (frame.inElse) throw syntaxError("Duplicate else", location);
      frame.inElse = true;
      output = frame.block.alternate;
      continue;
    }

    if (tag.startsWith("/")) {
      const closeKind = tag.slice(1).trim();
      if (closeKind !== "if" && closeKind !== "each") {
        throw syntaxError(`Unknown closing block '${tag}'`, location);
      }
      const frame = stack.at(-1);
      if (!frame) throw syntaxError(`Closing ${closeKind} without an open block`, location);
      if (frame.block.kind !== closeKind) {
        throw syntaxError(`Mismatched close: expected /${frame.block.kind}, got /${closeKind}`, location);
      }
      stack.pop();
      output = frame.parent;
      continue;
    }

    output.push({ kind: "value", path: tag, escaped: true, location });
  }

  const unclosed = stack.at(-1);
  if (unclosed) throw syntaxError(`Unclosed ${unclosed.block.kind} block`, unclosed.block.location);
  return root;
}

function property(value: unknown, key: string): unknown {
  if ((typeof value !== "object" && typeof value !== "function") || value === null) return undefined;
  return Object.prototype.hasOwnProperty.call(value, key)
    ? (value as Record<string, unknown>)[key]
    : undefined;
}

function follow(value: unknown, path: string[]): unknown {
  for (const part of path) value = property(value, part);
  return value;
}

function resolve(path: string, root: unknown, context: Context): unknown {
  if (path === "this") return context.current;
  if (path.startsWith("this.")) return follow(context.current, path.slice(5).split("."));
  if (path === "@index") return context.index;
  return follow(root, path.split("."));
}

function isTruthy(value: unknown): boolean {
  return !(
    value === "" || value === 0 || value === 0n || value === false ||
    value === null || value === undefined || (Array.isArray(value) && value.length === 0)
  );
}

function scalar(value: unknown, path: string, location: Location): string {
  if (value === null || value === undefined) return "";
